const D = { density: .6, energy: .62, speed: 1, scale: 1, hue: 28, x: .5, y: .5, poles: 3, style: 'field-heat', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, u = Math.min(W, H), TAU = 6.28318530718;
const clp = (v,a,b)=> v<a?a:v>b?b:v;
const style = P.style;

// --- seed-deterministic dipole rig (rebuild on seed / pole-count change) ---
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
const NP = clp(Math.round(P.poles), 2, 4);
if (S.seedUsed !== P.seed || S.npUsed !== NP) {
  S.seedUsed = P.seed; S.npUsed = NP; S.dips = [];
  for (let d = 0; d < NP; d++) {
    S.dips.push({
      oaBase:   fr(d*4+1) * TAU,
      orbitR:   0.09 + fr(d*4+2) * 0.17,
      orbitRate:(0.5 + fr(d*4+3)) * 0.09 * (fr(d*4+11) < 0.5 ? -1 : 1),
      oriBase:  fr(d*4+4) * TAU,
      rotRate:  (0.5 + fr(d*4+5)) * 0.12 * (fr(d*4+13) < 0.5 ? -1 : 1),
      sep:      0.05 + fr(d*4+6) * 0.06
    });
  }
}

// --- clock-driven dipole motion (continuous K.t drift = motion floor) ---
const spd  = 0.15 + P.speed;                 // never fully frozen even at speed 0
const tt   = K.t;
const sec  = K.section || 0;
const intn = K.intensity != null ? K.intensity : .6;
const midX = clp(P.x,0,1) * W, midY = clp(P.y,0,1) * H;
const orbK = 0.82 + 0.32 * Math.sin(sec * 0.7);   // section breathes the orbit radius
const strq = 0.7 + intn * 0.5;                    // section/intensity breathes strength
const hb   = (P.hue + sec * 7 + Math.sin(tt * 0.05) * 10 + 360) % 360;

const poles = [];
for (let d = 0; d < S.dips.length; d++) {
  const dp = S.dips[d];
  const oa = dp.oaBase + tt * dp.orbitRate * spd;
  const cx = midX + Math.cos(oa) * dp.orbitR * orbK * u;
  const cy = midY + Math.sin(oa) * dp.orbitR * orbK * u;
  const ori = dp.oriBase + tt * dp.rotRate * spd;
  const half = dp.sep * u * (0.7 + P.scale * 0.5);
  const hx = Math.cos(ori) * half, hy = Math.sin(ori) * half;
  poles.push({ x: cx + hx, y: cy + hy, q:  strq });
  poles.push({ x: cx - hx, y: cy - hy, q: -strq });
}

// --- analytic superposed dipole field (monopole pairs), normalized ~O(1) ---
const soft2 = (0.012 * u) * (0.012 * u);
function field(x, y) {
  let bx = 0, by = 0;
  for (let p = 0; p < poles.length; p++) {
    const pl = poles[p];
    const dx = x - pl.x, dy = y - pl.y;
    const inv = pl.q / (dx*dx + dy*dy + soft2) * u;
    bx += dx * inv; by += dy * inv;
  }
  return [bx, by];
}

// --- exposure / dramaturgy scalars ---
const briK = Math.min(1.7, 0.6 + P.energy*0.7 + intn*0.25 + K.pulse*0.15*P.energy + A.treble*0.4);
const eA   = 0.5 + P.energy * 0.9;
const stepLen = u * 0.011 * (0.5 + P.scale * 0.9);
const HALF = 3, STEPS = 6;

// --- ground veil (opaque repaint at alpha 100; translucent trails when < 100) ---
noStroke();
let gH, gS, gB;
if (style === 'iron-grey')      { gH = 40;  gS = 8;  gB = 86; }
else if (style === 'aurora')    { gH = 248; gS = 62; gB = 8; }
else if (style === 'neon-flux') { gH = (hb + 180) % 360; gS = 45; gB = 7; }
else if (style === 'blueprint') { gH = 213; gS = 72; gB = 26; }
else                            { gH = (hb + 205) % 360; gS = 58; gB = 12; }  // field-heat deep-blue ground
blendMode(BLEND);
fill(gH, gS, gB, P.alpha); rect(0, 0, W, H);

// --- pole glows: hot clusters + color + luminance lift (partial, never full-frame) ---
const pulseGlow = K.pulse * 8 * P.energy + A.bass * 20;
if (style === 'iron-grey') {
  push(); blendMode(MULTIPLY); noStroke();
  for (let p = 0; p < poles.length; p++) {
    const gr = u * (0.16 + 0.05 * intn);
    fill(35, 9, 72, 26); ellipse(poles[p].x, poles[p].y, gr*2.0, gr*2.0);
    fill(35, 12, 60, 30); ellipse(poles[p].x, poles[p].y, gr*0.9, gr*0.9);
  }
  blendMode(BLEND); pop();
} else {
  push(); blendMode(ADD); noStroke();
  const gr = u * (0.15 + 0.10 * intn) * (0.8 + P.energy * 0.5);
  const ga = Math.min(34, 9 + P.energy * 14 + pulseGlow);
  for (let p = 0; p < poles.length; p++) {
    const neg = poles[p].q < 0;
    let h1, h2, s1, s2;
    if (style === 'aurora')        { h1 = neg ? 285 : 150; s1 = 80; h2 = neg ? 300 : 130; s2 = 55; }
    else if (style === 'neon-flux'){ h1 = hb; s1 = 88; h2 = (hb + 22) % 360; s2 = 55; }
    else if (style === 'blueprint'){ h1 = 205; s1 = 30; h2 = 200; s2 = 12; }
    else                           { h1 = (hb + 14) % 360; s1 = 88; h2 = (hb + 44) % 360; s2 = 55; } // heat
    fill(h1, s1, 92, ga * 0.55); ellipse(poles[p].x, poles[p].y, gr*2.1, gr*2.1);
    fill(h2, s2, 100, ga);       ellipse(poles[p].x, poles[p].y, gr*0.85, gr*0.85);
  }
  blendMode(BLEND); pop();
}

// --- iron filings: short streamline slivers, colored by |B| (cool weak -> hot dense) ---
const glowStyle = (style === 'aurora' || style === 'neon-flux');
push();
if (glowStyle) blendMode(ADD);
const cols = Math.round(12 + P.density * 24);
const rows = Math.max(3, Math.round(cols * H / W));
const cw = W / cols, ch = H / rows;
for (let gy = 0; gy < rows; gy++) {
  for (let gx = 0; gx < cols; gx++) {
    const jx = (Math.sin((gx*12.9898 + gy*78.233 + P.seed*0.7)) * 43758.545) % 1;
    const jy = (Math.sin((gx*39.346 + gy*11.135 + P.seed*1.3)) * 24634.633) % 1;
    let x = (gx + 0.5 + (jx - 0.5) * 0.9) * cw;
    let y = (gy + 0.5 + (jy - 0.5) * 0.9) * ch;
    // back up half a needle so the sliver straddles the seed
    for (let k = 0; k < HALF; k++) {
      const b = field(x, y); const m = Math.sqrt(b[0]*b[0] + b[1]*b[1]) || 1e-6;
      x -= b[0] / m * stepLen; y -= b[1] / m * stepLen;
    }
    // integrate forward, drawing color-graded segments
    for (let k = 0; k < STEPS; k++) {
      const b = field(x, y); const m = Math.sqrt(b[0]*b[0] + b[1]*b[1]);
      if (m < 1e-5) break;
      const s = m / (m + 2.2);
      let sh, ss, sb, sa, sw;
      if (style === 'iron-grey')      { sh = 35;  ss = 6;  sb = clp(34 - s*26, 4, 40); sa = (52 + s*44) * eA; sw = 0.8 + s*1.4; }
      else if (style === 'aurora')    { sh = (s < 0.5 ? 288 - s*280 : 150 - (s-0.5)*40) % 360; ss = 80; sb = (34 + s*62) * briK; sa = (28 + s*52) * eA; sw = 0.9 + s*1.8; }
      else if (style === 'neon-flux') { sh = (hb + s*40) % 360; ss = 92 - s*30; sb = (44 + s*56) * briK; sa = (34 + s*54) * eA; sw = 1.0 + s*2.0; }
      else if (style === 'blueprint') { sh = 200; ss = clp(20 - s*18, 2, 20); sb = clp((60 + s*38) * briK, 46, 98); sa = (55 + s*40) * eA; sw = 0.8 + s*1.2; }
      else                            { sh = (hb + (1 - s) * 200) % 360; ss = clp(96 - s*40, 45, 100); sb = (24 + s*76) * briK; sa = (46 + s*50) * eA; sw = 0.8 + s*1.7; }
      stroke((sh + 360) % 360, ss, Math.min(100, sb), Math.min(100, sa));
      strokeWeight(sw);
      const nx = x + b[0] / m * stepLen, ny = y + b[1] / m * stepLen;
      line(x, y, nx, ny);
      x = nx; y = ny;
      if (x < -u*0.1 || x > W + u*0.1 || y < -u*0.1 || y > H + u*0.1) break;
    }
  }
}
pop();
blendMode(BLEND);
